  "meta": {
    "project_types": [
      "CLI"
    ],
    "project_notes": "Bounded local synthetic ACL checker for one concrete flow per invocation. Canonical accepted contracts govern semantics; generated graphs are derived. Preserve all matches and snapshot order without inferring a network path or end-to-end verdict.",
    "generated_at": "2026-10-16",
    "source_documents": [
      "requirements.md"
    ],
    "primary_language": "python",
    "target_languages": [
      "python"
