  },
  "background_and_overview": [
    {
      "id": "BG-001",
      "title": "Synthetic ACL Investigation",
      "description": "The prototype lets an operator investigate saved ACL evidence for one concrete traffic flow using small synthetic datasets. Human-readable output serves operators, while machine-readable output supports independent acceptance runs; no numerical load targets are specified.",
      "evidence": [
